export function itemInfo(s,id){if(!id)return null;const instance=s.gearInstances?.[id],baseId=instance?.base||id,g=Object.hasOwn(GEAR,baseId)?GEAR[baseId]:null;if(!g)return null;const out={...g,id,baseId,treasure:!!TREASURES[baseId],affix:instance?.affix||null,locked:!!s.lockedItems?.includes(id)};if(out.affix){out[out.affix.stat]=(out[out.affix.stat]||0)+out.affix.value;out.affixLabel=AFFIX_NAMES[out.affix.stat]+' +'+out.affix.value;}else out.affixLabel='';out.displayName=g.name+(out.affixLabel?'·'+out.affixLabel:'');return out;}
export function activeTreasures(s){const out={...(s.activatedTreasures||{})};for(const id of Object.values(s.equipment||{})){const g=itemInfo(s,id);if(g?.treasure&&!out[g.baseId])out[g.baseId]=id;}return out;}
export function treasureInfo(s,base){if(!TREASURES[base])return null;const activeId=activeTreasures(s)[base],owned=Object.keys(s.inventory).filter(id=>s.inventory[id]>0&&itemInfo(s,id)?.baseId===base),id=activeId||owned[0]||base,known=!!activeId||owned.length>0||treasureSourceCompleted(s,base);return {...itemInfo(s,id),active:!!activeId,known,copies:owned.reduce((n,id)=>n+s.inventory[id],0),source:TREASURES[base].source,effect:TREASURES[base].effect};}
export function treasureSourceCompleted(s,base){return base==='bell'?s.tower>=5:base==='mountainSeal'?s.finale>=3:base==='skyMirror'?s.foundationFinale>=3:!!TREASURES[base]?.area&&s.cleared.includes(TREASURES[base].area);}
export function treasureResonances(s,details=true){const active=activeTreasures(s);return TREASURE_RESONANCES.map(r=>{const members=r.members.map(id=>details?{id,...treasureInfo(s,id)}:{id,active:!!active[id]}),count=members.filter(t=>t.active).length;return {...r,members,count,tiers:r.tiers.map(t=>({...t,active:count>=t.count}))};});}
export function techniqueCombo(s){const load=s.combatLoadout||{};for(const group of TECHNIQUE_COMBOS){const recipe=group.recipes.find(r=>load.main===r.main&&load.aux===r.aux&&s.techniques[r.main]>0&&s.techniques[r.aux]>0);if(recipe)return {...recipe,group:group.id,name:group.name,style:group.style};}return null;}
function wearableEquipment(s,equipment=s.equipment){return Object.fromEntries(Object.keys(SLOTS).map(slot=>[slot,itemInfo(s,equipment[slot])?.treasure?null:equipment[slot]]));}
export function migrateTreasures(s){s.activatedTreasures??={};const u=s.dismantleUndo;if(u?.equipmentBefore&&u?.equipmentAfter&&u.treasureRestoreAllowed===undefined&&[...Object.values(u.equipmentBefore),...Object.values(u.equipmentAfter)].some(id=>itemInfo(s,id)?.treasure))u.treasureRestoreAllowed=Object.keys(SLOTS).every(slot=>s.equipment[slot]===u.equipmentAfter[slot]);const moved=[];for(const [slot,id]of Object.entries(s.equipment)){const g=itemInfo(s,id);if(g?.treasure){if(!s.activatedTreasures[g.baseId])s.activatedTreasures[g.baseId]=id;s.equipment[slot]=null;moved.push(g.baseId);}}return moved;}
