export function specialization(s){const choices=Object.hasOwn(SPECIALIZATIONS,s.sect)?SPECIALIZATIONS[s.sect]:null;return s.specialtyTrials?.[s.sect]&&choices?choices.find(x=>x.id===s.specializations?.[s.sect])||null:null;}
export function specialtyInfo(s){const t=Object.hasOwn(SPECIALTY_TRIALS,s.sect)?SPECIALTY_TRIALS[s.sect]:null;if(!t)return null;const done=!!s.specialtyTrials?.[s.sect],available=s.level>=11&&(s.sectTrials?.[s.sect]||0)>=3;return {...t,sect:s.sect,done,available,reason:s.level<11?'筑基一层开放专修试炼':(s.sectTrials?.[s.sect]||0)<3?'先通过本门三阶执事试炼':done?'已解锁两条专修，可脱战免费改换':'条件已满足，首胜解锁专修'};}
export function specializationPreview(s,id){const info=specialtyInfo(s),choice=info&&SPECIALIZATIONS[s.sect].find(x=>x.id===id);if(!info||id!==null&&(!choice||!info.done))return {ok:false,reason:!info?'先拜入宗门':!info.done?'先通过本门专修试炼':'请选择本门专修'};const next={...s,specializations:{...s.specializations,[s.sect]:id}};return {ok:true,next,choice,signature:JSON.stringify([s.runId,s.level,s.sect,s.specialtyTrials,s.specializations,id,stats(s),stats(next),cultivation(s),cultivation(next),combatProfile(s),combatProfile(next)])};}
