const NUM=['','一','二','三','四','五','六','七','八','九'];
export const realmChapter=level=>level>=21?'core':level>=11?'foundation':'qi';
export const stageName=level=>level>23?'金丹中期（未开放）':(level>=21?'金丹':level>=11?'筑基':'炼气')+((level===10||level===20)?'圆满':NUM[level>=21?level-20:level>=11?level-10:level]+'层');
export const levelName=s=>s.level>=21?`金丹 · ${NUM[s.level-20]}层`:s.level>=11?`${s.foundationType==='heaven'?'天道筑基':'普通筑基'} · ${s.foundationExtreme?'极境':s.level===20?'圆满':NUM[s.level-10]+'层'}`:s.extreme?'炼气 · 极境':s.level===10?'炼气 · 圆满':`炼气 · ${NUM[s.level]}层`;
export const chapterLabel=s=>s?.level>=21?'金丹初卷':s?.level>=11?'筑基卷':'炼气卷';
export const needExp=s=>NEED[s.level]??80000;
export const enhancementLimit=s=>s.level>=11?15:10;
export function foundationChoice(s,id=s.foundationPath){const path=FOUNDATION_PATHS[id];return s.level>=11&&path?{id,name:path.name,...path[s.foundationType==='heaven'?'heaven':'normal']}:null;}
export function breakthroughInfo(s){const need=needExp(s),cap=s.level===10||s.level===20||s.level>=23,cost=s.level>=21&&s.level<23?{stones:5000+(s.level-21)*3000,jade:80+(s.level-21)*40}:s.level>=11&&s.level<20?{stones:500+(s.level-11)*250,jade:10+(s.level-11)*4}:{},area=({12:'reed',15:'forge',18:'mirror',19:'abyss',21:'dawn',22:'furnace'})[s.level]||null,cleared=!area||s.cleared.includes(area),ready=!cap&&s.exp>=need&&afford(s,cost)&&cleared;return {need,cost,area,cleared,cap,ready,reason:cap?s.level>=23?'金丹初期境界已达本章上限，修为仍可积累':'已至当前境界圆满':!cleared?'先通关'+AREAS.find(a=>a.id===area).name:s.exp<need?'修为尚不足':!afford(s,cost)?'破境材料不足':'条件已满足'};}
export function setCounts(s){const out={};for(const id of Object.values(s.equipment)){const set=itemInfo(s,id)?.set;if(set)out[set]=(out[set]||0)+1;}return out;}
