export function towerEnemy(floor){if(floor>10)return {name:`问心塔 · 第 ${floor} 层守灵`,hp:1500+(floor-10)*700,atk:120+(floor-10)*40,def:60+(floor-10)*15};return {name:`问心塔 · 第 ${floor} 层守灵`,hp:115+floor*42+floor*floor*5,atk:21+floor*8,def:5+floor*3};}
export const towerCap=s=>s.level<3?0:s.level<11?10:Math.min(15,11+Math.floor((s.level-11)/2));
