export const PRESET_NAMES={cultivation:'修炼',battle:'闯关'};
export function capturePreset(s){return {equipment:{...s.equipment},combatLoadout:{...s.combatLoadout},foundationPath:s.level>=11?s.foundationPath:null,specialty:s.sect?{sect:s.sect,id:s.specializations?.[s.sect]||null}:null};}
