export function presetPreview(s,p){const issues=[];if(!p||p.invalid||!p.equipment||!p.combatLoadout)return {ok:false,issues:[p?'这份预设记录不完整，请重新保存当前配置':'尚未保存配置'],next:null,signature:JSON.stringify([s.runId,p])};for(const slot of Object.keys(SLOTS)){const id=p.equipment[slot];if(id===null)continue;const g=itemInfo(s,id);if(!g||g.slot!==slot||g.treasure)issues.push(SLOTS[slot]+'记录无效');else if(!(s.inventory[id]>0))issues.push('缺少 '+g.displayName);else if(s.level<(g.gate||1))issues.push(g.name+'需'+stageName(g.gate));}const {main,aux}=p.combatLoadout;for(const [label,id]of [['主修',main],['辅修',aux]]){if(label==='主修'&&id==='sect'||label==='辅修'&&id===null)continue;const t=TECHNIQUES.find(t=>t.id===id);if(!t||!s.techniques[id])issues.push(label+'功法未学或记录无效');else if(s.level<(t.gate||1))issues.push(t.name+'需'+stageName(t.gate));}if(main===aux)issues.push('主辅功法不能重复');if(p.foundationPath!==null&&(!Object.hasOwn(FOUNDATION_PATHS,p.foundationPath)||s.level<11))issues.push('本道基需先完成筑基');if(p.specialty&&(p.specialty.sect!==s.sect||!specializationPreview(s,p.specialty.id).ok))issues.push(p.specialty.sect!==s.sect?'这份预设记录了其他宗门专修，请先自行改换宗门':'这份预设的专修尚未解锁');const next=issues.length?null:{...s,...(p.specialty?{specializations:{...s.specializations,[s.sect]:p.specialty.id}}:{}),equipment:{...p.equipment},combatLoadout:{...p.combatLoadout},foundationPath:p.foundationPath===null?s.foundationPath:p.foundationPath};const summary=x=>({stats:stats(x),combat:combatProfile(x),cultivation:cultivation(x),sets:setCounts(x)}),current=summary(s),after=next?summary(next):null;return {ok:!issues.length,issues,next,current,after,signature:JSON.stringify([s.runId,s.level,s.foundationType,s.enhance,capturePreset(s),p,current,after,issues])};}
export function presetSignature(s,key,mode='apply'){const p=mode==='save'?capturePreset(s):s.presets?.[key];return JSON.stringify([s.presets?.[key]||null,presetPreview(s,p).signature]);}
export function presetDismantleWarnings(s,items){const remaining=new Map(items.map(r=>[r.id,(s.inventory[r.id]||0)-r.count])),out=[];for(const [key,name]of Object.entries(PRESET_NAMES)){const p=s.presets?.[key];if(!p?.equipment)continue;const ids=[...new Set(Object.values(p.equipment).filter(id=>id&&remaining.has(id)&&remaining.get(id)<1))];if(ids.length)out.push({key,name,ids});}return out;}

