export const GUIDE=[{id:'cultivate',title:'先开始修炼',text:'点「开始修炼」。基础每 30 秒获得 6 修为，满后可手动突破，修为仍持续累计。',tab:'home'}, {id:'clear',title:'去青溪渡历练',text:'打开山河图，挑战青溪渡。点「首次自动挑战」，会自动应对蓄势；也可切换手动。',tab:'map'}, {id:'farm',title:'把通关地设为挂机',text:'青溪渡胜利后，点「在此挂机」，选择持续、次数或时长。',tab:'map'}, {id:'learn',title:'学一门功法',text:'打开功法页，研习「归元吐纳诀」。学会后，每次修炼得到更多修为；升级和主辅配置也在这里。',tab:'techniques'}, {id:'sect',title:'选择自己的流派',text:'气修擅长修炼，剑修擅长攻伐，体修擅长生存。入门不收费。',tab:'sect'}, {id:'equip',title:'穿戴并强化装备',text:'首通会获得装备。行囊中点物品比较、换装，强化留在栏位。山河钟与问山印请在「法宝录」激活，多件叠加，不占六格。',tab:'bag'}];
export function guideDone(s,id){return s.tutorial.done.includes(id)||(id==='cultivate'&&s.cultivating)||(id==='clear'&&s.cleared.length>0)||(id==='farm'&&!!s.farm)||(id==='learn'&&Object.keys(s.techniques).length>0)||(id==='sect'&&!!s.sect)||(id==='equip'&&Object.values(s.equipment).some(id=>id&&!['wood','linen'].includes(id)));}

export function gearComparison(s,id){const g=itemInfo(s,id);if(!g||g.treasure)return null;const preview=clone(s);preview.equipment[g.slot]=id;const current=stats(s),next=stats(preview);return {current,next,delta:Object.fromEntries(Object.keys(current).map(k=>[k,next[k]-current[k]])),currentItem:s.equipment[g.slot],nextSets:setCounts(preview),currentSets:setCounts(s)};}

export const DISMANTLE_VALUE={common:1,fine:3,rare:8,epic:18,artifact:50};
export function dismantleValue(s,id){return DISMANTLE_VALUE[itemInfo(s,id)?.quality]||0;}
export function dismantleCapacity(s,id,equipment=s.equipment){const g=itemInfo(s,id);return !g||g.locked?0:Math.max(0,(s.inventory[id]||0)-(Object.values(equipment).includes(id)?1:0));}
function validEquipment(s,equipment){return equipment&&Object.keys(equipment).length===Object.keys(SLOTS).length&&Object.keys(SLOTS).every(slot=>equipment[slot]===null||s.inventory[equipment[slot]]>0&&itemInfo(s,equipment[slot])?.slot===slot&&!itemInfo(s,equipment[slot])?.treasure);}
export function dismantlePlan(s,equipment=s.equipment){const items=[];for(const [id]of Object.entries(s.inventory)){const count=dismantleCapacity(s,id,equipment);if(count>0)items.push({id,count,each:dismantleValue(s,id)});}return {items,count:items.reduce((n,x)=>n+x.count,0),ore:items.reduce((n,x)=>n+x.count*x.each,0)};}

export function areaEvent(id){if(Object.hasOwn(CORE_EVENTS,id))return CORE_EVENTS[id];if(Object.hasOwn(FOUNDATION_FIELD_EVENTS,id)){const e=FOUNDATION_FIELD_EVENTS[id];return {title:e.title,text:e.text,choices:[{id:'insight',label:e.insight,rewards:{exp:300},result:'山中故事记入心间，修为 +300。'},{id:'jade',label:e.jade,rewards:{jade:6},result:'收拢旅途所得，灵髓 +6。'}]};}const events={brook:{title:'溪边相逢',text:'一名采药人困在涨水的浅溪旁，竹篓里有刚采下的灵草。',choices:[{id:'help',label:'护送过溪',rewards:{stones:20},result:'采药人平安过溪，赠你 20 灵石。'},{id:'herb',label:'一同寻药',rewards:{herbs:5},result:'你认出溪岸的回春草，得到 5 灵草。'}]},bamboo:{title:'竹简残篇',text:'老竹下埋着半卷吐纳残篇，几行字仍有灵息。',choices:[{id:'read',label:'参悟残篇',rewards:{exp:25},result:'你静观残篇，修为 +25。'},{id:'water',label:'采集竹露',rewards:{herbs:8},result:'晨露凝在竹叶上，灵草 +8。'}]},cliff:{title:'崖间旧炉',text:'废弃锻炉里仍残留微光，石缝中结着一枚灵髓。',choices:[{id:'ore',label:'收拢炉料',rewards:{ore:12},result:'收拢残炉玄铁 +12。'},{id:'jade',label:'取出灵髓',rewards:{jade:2},result:'石缝中取出灵髓 +2。'}]},marsh:{title:'泽畔夜灯',text:'摆渡人的灯火映着月色。他愿以船上的物资换你讲一段山中见闻。',choices:[{id:'pill',label:'谈草木之道',rewards:{pills:2},result:'交换修行见闻，获回春丹 +2。'},{id:'exp',label:'听月下潮声',rewards:{exp:80},result:'潮生潮落之间，修为 +80。'}]},peak:{title:'陨星碎光',text:'落星峰的碎石里，灵光与金铁交织。',choices:[{id:'ore',label:'炼出星铁',rewards:{ore:25},result:'拾取陨星玄铁 +25。'},{id:'jade',label:'凝聚灵髓',rewards:{jade:5},result:'凝聚灵髓 +5。'}]},gate:{title:'石台留问',text:'石台上一句旧问仍未磨灭：此生所求，究竟为何？',choices:[{id:'exp',label:'坐忘观心',rewards:{exp:180},result:'心念渐澄，修为 +180。'},{id:'jade',label:'留一缕道意',rewards:{jade:8},result:'道意结晶，灵髓 +8。'}]}};return events[id]||events.brook;}
export function resourceGoal(s,required,purpose='所需材料'){const missing=Object.entries(required).filter(([k,n])=>(s[k]||0)<n);if(!missing.length)return null;const resource=(missing.find(([k])=>k==='jade')||missing[0])[0],areas=AREAS.filter(a=>a.gate<=s.level&&s.cleared.includes(a.id)&&(a[resource]||0)>0).sort((a,b)=>b[resource]/b.seconds-a[resource]/a.seconds),area=areas[0],gap=missing.map(([k,n])=>`${Math.ceil(n-(s[k]||0))} ${RES[k]}`).join('、');return {title:`准备${purpose} · ${RES[resource]}`,reason:`还缺 ${gap}。${area?`${area.name}已通关，每${area.seconds}秒可得${area[resource]}${RES[resource]}`:'查看获取途径，先通关对应地图再挂机'}`,tab:'map',target:'resources',resource};}
function recoveryGoal(s,destination){if(s.hp>=stats(s).hp*.65)return null;return {title:s.herbs>=2?'先调息，再'+destination:'等待气血恢复，再'+destination,reason:s.herbs>=2?'消耗2灵草即可回满气血，调息不会丢失进度':'脱战每10秒恢复5%最大气血；恢复后再挑战，修炼和挂机可同时继续',tab:s.herbs>=2?'bag':'home',target:s.herbs>=2?'rest':'recovery'};}
function commissionGoal(s){const m=missionStatus(s);return m?.ready?{title:'交付已完成的宗门委托',reason:`${m.name}已达标，可得${m.contribution}贡献和${m.stones}灵石`,tab:'sect',target:'mission'}:null;}
export function nextGoal(s){if(s.level>=21)return coreGoal(s);if(s.level>=11)return foundationGoal(s);if(s.battle)return {title:'先完成眼前斗法',reason:enemyIntent(s.battle).detail,tab:'home',target:'battle'};if(!s.cultivating)return {title:'开启吐纳，让修为持续累计',reason:`每 ${cultivation(s).interval} 秒获得 ${cultivation(s).gain} 修为`,tab:'home',target:'cultivate'};if(s.level<10&&s.exp>=needExp(s))return {title:'修为已足，可以突破',reason:`扣除 ${needExp(s)} 修为，剩余 ${Math.round((s.exp-needExp(s))*10)/10} 点保留`,tab:'home',target:'breakthrough'};if(!s.cleared.length)return recoveryGoal(s,'历练青溪渡')||{title:'首通青溪渡，开启挂机',reason:'获得灵石、材料与第一件装备',tab:'map',target:'brook'};if(!s.farm){const a=AREAS.filter(a=>s.cleared.includes(a.id)&&s.level>=a.gate).at(-1);if(a)return {title:`在${a.name}开启挂机`,reason:`每 ${a.seconds} 秒自动带回 ${a.stones} 灵石及材料`,tab:'map',target:a.id};}if(!s.techniques.breath)return resourceGoal(s,techCost(s,'breath'),'归元吐纳诀学费')||{title:'研习归元吐纳诀',reason:`${techCost(s,'breath').stones}灵石，单次修为增加20%`,tab:'techniques',target:'breath'};if(!s.sect)return {title:'选择一座山门与战斗流派',reason:'术修破防、剑修爆发、体修续航；首次免费',tab:'sect',target:'sect'};const mission=commissionGoal(s);if(mission)return mission;const available=AREAS.find(a=>a.gate<=s.level&&!s.cleared.includes(a.id));if(available){const healing=recoveryGoal(s,'探索'+available.name);if(healing)return healing;const st=stats(s);if(st.atk<=available.def+15&&!s.techniques.sword)return resourceGoal(s,techCost(s,'sword'),'松风剑诀学费')||{title:'研习松风剑诀，补足攻伐',reason:`准备挑战${available.name}；首重需要${techCost(s,'sword').stones}灵石，攻伐+8%`,tab:'techniques',target:'sword'};return {title:`探索${available.name}`,reason:`已达开放境界，首通后可挂机。对手攻伐 ${available.atk} / 护体 ${available.def}`,tab:'map',target:available.id};}if(s.level===10)return resourceGoal(s,{stones:400,jade:12},s.extreme?'天道筑基材料':'普通筑基材料')||{title:'选择道基，踏入'+(s.extreme?'天道筑基':'普通筑基'),reason:s.extreme?'炼气极境已成，20%根基保留，先预览道基再确认':'圆满即可筑基；也可先凝练极境走天道路线。打开预览不会消耗资源',tab:'home',target:'ascend'};if(s.level>=3&&s.tower<10){const healing=recoveryGoal(s,'挑战问心塔');return healing||{title:`尝试问心塔第 ${s.tower+1} 层`,reason:'逐层收集塔印，第5与10层首通获得神器',tab:'map',target:'tower'};}const cycle=techStudyInfo(s,'cycle');if(cycle.available&&cultivation(s).interval>10)return {title:(cycle.level?'升级':'研习')+'小周天诀，加快吐纳',reason:`${cycle.price.stones}灵石，下一重缩短6%修炼间隔；最短10秒`,tab:'techniques',target:'cycle'};return {title:`继续修炼，准备${stageName(s.level+1)}`,reason:`还需 ${Math.max(0,Math.round((needExp(s)-s.exp)*10)/10)} 修为。已学功法持续叠加，修为达到后再手动突破`,tab:'home',target:'progress'};}


function normalizeLedger(raw,now,s){const out=emptyFarmLedger(Number.isFinite(raw?.since)?raw.since:now,Number.isInteger(raw?.serial)&&raw.serial>=0?raw.serial:0);if(!raw||typeof raw!=='object')return out;for(const k of ['elapsed','rounds','stones','ore','herbs','jade'])out[k]=Number.isFinite(raw[k])&&raw[k]>=0?raw[k]:0;for(const k of ['items','areas'])if(raw[k]&&typeof raw[k]==='object')for(const [id,n]of Object.entries(raw[k]))if(Number.isInteger(n)&&n>0&&(k==='items'?itemInfo(s,id):AREAS.some(a=>a.id===id)))out[k][id]=n;return out;}

export function equipmentWeights(s){return ({blade:{atk:7,def:2,hp:.35},jade:{atk:6,def:3,hp:.45},stone:{atk:3,def:5,hp:.75},wanderer:{atk:5,def:4,hp:.6}})[combatProfile(s).style];}
export function equipmentScoreParts(s){const st=stats(s),p=combatProfile(s),w=equipmentWeights(s),coeff={atk:w.atk+.5*p.scale+.8*p.pierce+2*p.setBurst,def:w.def+.3*p.shield,hp:w.hp+2*(p.heal+p.setHeal+p.guardHeal)+(p.bell?.08:0)+.1*p.dodge};return {stats:st,coeff,score:Math.round(st.atk*coeff.atk+st.def*coeff.def+st.hp*coeff.hp)};}
export function equipmentScore(s){return equipmentScoreParts(s).score;}
function itemEffectKey(g){return g.set?'set:'+g.set:g.quality==='artifact'?'artifact:'+g.baseId:'plain';}
export function recommendEquipment(s){s={...s,activatedTreasures:activeTreasures(s),equipment:wearableEquipment(s)};const slots=Object.keys(SLOTS),groups=slots.map(slot=>{const all=Object.keys(s.inventory).filter(id=>s.inventory[id]>0&&itemInfo(s,id)?.slot===slot&&!itemInfo(s,id)?.treasure).map(id=>({id,g:itemInfo(s,id)}));const kept=all.filter((a,i)=>!all.some((b,j)=>i!==j&&itemEffectKey(a.g)===itemEffectKey(b.g)&&['atk','def','hp'].every(k=>(b.g[k]||0)>=(a.g[k]||0))&&(['atk','def','hp'].some(k=>(b.g[k]||0)>(a.g[k]||0))||j<i&&['atk','def','hp'].every(k=>(b.g[k]||0)===(a.g[k]||0)))));return kept.length?kept:[{id:null,g:{}}];});const bare={...s,extreme:false,foundationExtreme:false,equipment:Object.fromEntries(slots.map(k=>[k,null]))},d=statBreakdown(bare),p=combatProfile(bare),w=equipmentWeights(bare),base=d.subtotal,sources=bonusSources(bare).filter(r=>r.name!=='山河钟'),bonus=Object.fromEntries(['gain','speed','atk','def','hp'].map(k=>[k,sources.reduce((n,r)=>n+(r[k]||0),0)]));let best={equipment:{...s.equipment},score:equipmentScore(s),evaluated:0},equipment={};const visit=(i,atk,def,hp,bamboo,moon,tide,ember,bell,sword)=>{if(i===slots.length){let pa=bonus.atk,pd=bonus.def,ph=bonus.hp;if(bamboo>=2)ph+=.15;if(moon>=2)pa+=.15;if(moon>=3)pd+=.2;if(tide>=2)ph+=.2;if(tide>=3)pd+=.15;if(ember>=2)pa+=.2;if(s.extreme){pa+=.2;pd+=.2;ph+=.2;}if(s.foundationExtreme){pa+=.2;pd+=.2;ph+=.2;}if(p.bell){pa+=.12;pd+=.12;ph+=.12;}if(sword)pa+=.18;const a=Math.round((base.atk+atk)*(1+pa)),d0=Math.round((base.def+def)*(1+pd)),h=Math.round((base.hp+hp)*(1+ph)),score=Math.round(a*(w.atk+.5*p.scale+.8*p.pierce+2*((moon>=3?.2:0)+(ember>=3?.3:0)))+d0*(w.def+.3*p.shield)+h*(w.hp+2*(p.heal+(bamboo>=3?.03:0)+(tide>=3?.04:0)+p.guardHeal)+(p.bell?.08:0)+.1*p.dodge));best.evaluated++;if(score>best.score)best={equipment:{...equipment},score,evaluated:best.evaluated};return;}for(const {id,g}of groups[i]){equipment[slots[i]]=id;visit(i+1,atk+(g.atk||0),def+(g.def||0),hp+(g.hp||0),bamboo+(g.set==='bamboo'?1:0),moon+(g.set==='moon'?1:0),tide+(g.set==='tide'?1:0),ember+(g.set==='ember'?1:0),bell||g.baseId==='bell',sword||g.baseId==='sword');}};visit(0,0,0,0,0,0,0,0,false,false);return best;}
export function inferiorPlan(s){return dismantlePlan(s);}
export function bagCount(s){return Object.values(s.inventory).reduce((n,x)=>n+x,0);}

export function shopDiscount(s){return s.sect&&(s.sectTrials?.[s.sect]||0)>=3?.1:0;}
export const shopPrice=(s,id)=>Math.ceil((GEAR[id]?.price||0)*(1-shopDiscount(s)));
export function farmPlan(p){if(!p||p.mode==='unlimited')return {mode:'unlimited'};if(p.mode==='rounds'){const n=p.remainingRounds??p.value;return Number.isInteger(n)&&n>=0&&n<=10000?{mode:'rounds',remainingRounds:n}:null;}if(p.mode==='duration'){const n=p.remainingSeconds??p.value*60;return Number.isFinite(n)&&n>=0&&n<=28800?{mode:'duration',remainingSeconds:n}:null;}return null;}
export function autoMove(s){const b=s.battle;if(!b)return 'strike';const st=stats(s),p=combatProfile(s),def=enemyDefense(b),skill=Math.max(1,Math.round(st.atk*(p.scale+p.setBurst))-Math.round(def*(1-p.pierce))),strike=Math.max(1,st.atk-def);if(strike>=b.hp)return 'strike';if(s.qi>=p.cost&&skill>=b.hp)return 'skill';if(b.usePills&&s.pills&&s.hp<st.hp*.35)return 'pill';if(b.areaTrial&&b.id==='reed'&&enemyIntent(b).charged&&s.qi>=p.cost&&s.hp>Math.max(st.hp*.55,b.atk*1.5-st.def))return 'skill';if(enemyIntent(b).charged)return 'guard';if(b.areaTrial&&b.id==='abyss'&&(b.pressure||0)>=2)return 'guard';if(b.areaTrial&&b.id==='mirror'&&b.lastMove==='skill'&&s.qi>=p.cost)return 'strike';return s.qi>=p.cost?'skill':'guard';}
export function trialEnemy(type,n){if(type==='core')return CORE_TRIAL;if(type==='foundation')return FOUNDATION_TRIALS[n-1];if(type==='sect')return {name:['','山门守心人','静修台执印人','藏经阁守卷人','巡山道使','传法守印人'][n],hp:[0,220,440,760,2400,4400][n],atk:[0,33,58,85,190,300][n],def:[0,8,17,28,70,120][n]};if(type==='extreme')return {name:'天外一念',hp:1800,atk:140,def:48};return {name:['','照心试·旧我','渡劫试·风雷','问山终试·道影'][n],hp:[0,650,1000,1300][n],atk:[0,90,100,115][n],def:[0,25,35,40][n]};}
export function missionStatus(s){if(!s.mission)return null;const m=s.mission,hunts=Object.values(s.explored).reduce((n,v)=>n+v,0),info={hunt:{name:'巡守山道',progress:hunts-m.hunts,need:3,contribution:40,stones:60,desc:'接取后赢得3场区域战斗（手动或自动均可，挂机不计）'},farm:{name:'山门采办',progress:s.farmRounds-m.rounds,need:10,contribution:30,stones:40,desc:'接取后完成10轮挂机'},herbs:{name:'药圃补给',progress:s.herbs,need:10,contribution:25,stones:30,desc:'交付10株灵草'}}[m.kind];return {...info,ready:info.progress>=info.need};}

function foundationGoal(s){if(s.battle)return {title:'先完成眼前斗法',reason:enemyIntent(s.battle).detail,tab:'home',target:'battle'};if(!s.foundationPath)return {title:'选择本道基，开启筑基修行',reason:'锋行、厚土、灵息各有所长，脱战可免费改换',tab:'home',target:'foundationPath'};if(!s.cultivating)return {title:'开启凝元吐纳',reason:'筑基基础每30秒获得24修为，既有功法继续叠加',tab:'home',target:'cultivate'};const b=breakthroughInfo(s);if(b.ready)return {title:'破境条件已齐，可以进阶',reason:'扣除所需修为与材料，剩余全部保留',tab:'home',target:'breakthrough'};if(b.area&&!b.cleared)return recoveryGoal(s,'探索'+AREAS.find(a=>a.id===b.area).name)||{title:'通关'+AREAS.find(a=>a.id===b.area).name+'，稳固道基',reason:'此处是下一层的历练要求，存储修为不会丢失',tab:'map',target:b.area};if(!b.cap&&s.exp>=b.need){const resource=resourceGoal(s,b.cost,'破境材料');if(resource)return resource;}const mission=commissionGoal(s);if(mission)return mission;const next=FOUNDATION_AREAS.find(a=>a.gate<=s.level&&!s.cleared.includes(a.id));if(next)return recoveryGoal(s,'探索'+next.name)||{title:'探索'+next.name,reason:next.desc+' 首通后可以挂机。',tab:'map',target:next.id};const farm=FOUNDATION_AREAS.filter(a=>a.gate<=s.level&&s.cleared.includes(a.id)).at(-1);if(farm&&(!s.farm||AREAS.find(a=>a.id===s.farm)?.gate<11))return {title:'在'+farm.name+'收集筑基装备',reason:'主掉落与三部位继续按累计轮数发放',tab:'map',target:farm.id};if(!s.techniques.foundationBreath)return resourceGoal(s,techCost(s,'foundationBreath'),'凝元真诀学费')||{title:'研习凝元真诀',reason:`首重${techCost(s,'foundationBreath').stones}灵石，增加单次修为和护体`,tab:'techniques',target:'foundationBreath'};if(s.level>=20&&s.foundationFinale<3)return recoveryGoal(s,'挑战问基三试')||{title:'完成问基三试第'+(s.foundationFinale+1)+'关',reason:'普通筑基圆满即可，不要求天道或极境；最终获得观澜镜',tab:'map',target:'foundation'};if(s.level===20&&s.foundationFinale>=3)return resourceGoal(s,CORE_COST,'结丹材料')||{title:s.exp>=CORE_EXP?'准备结丹，开启金丹初卷':'积累修为，准备结丹',reason:`需要${CORE_EXP}修为，余量保留。筑基极境可选；结丹后不能补炼`,tab:'home',target:'corePrepare'};if(s.tower<15&&s.level>=11+Math.max(0,s.tower-10)*2)return recoveryGoal(s,'挑战问心塔')||{title:'挑战问心塔第'+(s.tower+1)+'层',reason:'筑基层守灵逐层开放，第15层首通另得40灵髓',tab:'map',target:'tower'};if(s.level<20)return {title:'积累修为，准备'+stageName(s.level+1),reason:`还需${Math.max(0,Math.round((b.need-s.exp)*10)/10)}修为；破境另需${b.cost.stones}灵石、${b.cost.jade}灵髓`,tab:'home',target:'progress'};return resourceGoal(s,CORE_COST,'结丹材料')||{title:s.exp>=CORE_EXP?'准备结丹，开启金丹初卷':'积累修为，准备结丹',reason:`问基三试已完成；结丹需要${CORE_EXP}修为，余量保留。筑基极境可选，进入金丹后无法补炼`,tab:'home',target:'corePrepare'};}

export function corePreview(s){const ready=s.level===20&&s.foundationFinale>=3&&s.exp>=CORE_EXP&&afford(s,CORE_COST),next={...s,level:21};return {ready,next,cost:{...CORE_COST},need:CORE_EXP,reason:s.level!==20?'筑基圆满时可以结丹':s.foundationFinale<3?'先完成筑基问基三试':s.exp<CORE_EXP?'结丹修为尚不足':!afford(s,CORE_COST)?'结丹材料尚不足':'已具备结丹条件',signature:JSON.stringify([s.runId,s.level,s.foundationFinale,s.extreme,s.foundationExtreme,s.foundationType,s.foundationPath,capturePreset(s),stats(s),stats(next),cultivation(s),cultivation(next)])};}
function coreGoal(s){if(s.battle)return {title:'完成眼前斗法',reason:enemyIntent(s.battle).detail,tab:'map',target:'battle'};if(!s.cultivating)return {title:'开启金丹吐纳',reason:'基础每30秒60修为，原有被动和套组继续叠加',tab:'home',target:'cultivate'};const b=breakthroughInfo(s);if(b.ready)return {title:'条件齐备，进阶'+stageName(s.level+1),reason:'只扣所需修为与材料，剩余继续积累',tab:'home',target:'breakthrough'};const next=CORE_AREAS.find(a=>a.gate<=s.level&&!s.cleared.includes(a.id));if(next)return recoveryGoal(s,'探索'+next.name)||{title:'探索'+next.name,reason:next.desc+' 首通开启挂机，也是下一层的历练条件。',tab:'map',target:next.id};if(s.level>=23&&!s.coreFinale)return recoveryGoal(s,'挑战金丹初试')||{title:'完成金丹初试，收束初期小卷',reason:'普通/天道均可挑战；首胜获得5000灵石、200玄铁、100灵髓',tab:'map',target:'core'};if(!s.techniques.coreBreath)return resourceGoal(s,techCost(s,'coreBreath'),'金息吐纳篇学费')||{title:'研习金息吐纳篇',reason:'原有被动继续叠加；每重再增加20%单次修为',tab:'techniques',target:'coreBreath'};const farm=CORE_AREAS.filter(a=>s.cleared.includes(a.id)).at(-1);if(farm&&s.farm!==farm.id)return {title:'在'+farm.name+'收集金丹初期装备',reason:'通关后按同样的累计5轮规则掉落，15轮覆盖道冠、靴履和腰带',tab:'map',target:farm.id};if(s.level<23)return resourceGoal(s,b.cost,'进阶材料')||{title:'积累修为，准备'+stageName(s.level+1),reason:`还需${Math.max(0,Math.round(b.need-s.exp))}修为；旧功法、道基与法宝仍有效`,tab:'home',target:'progress'};return {title:'金丹初卷已成，继续打磨配装',reason:'本次开放到金丹三层，后续境界尚未开放。修为不封顶，挂机与旧章节仍可继续',tab:'bag',target:'gear'};}
